 15	class PricingTest {
 16	
 17	    private static Pricing quote(String plan, int room, String in, String out, String company) {
 18	        Stay stay = new Stay(Room.find(room).orElseThrow(), LocalDate.parse(in), LocalDate.parse(out), company);
 19	        return RatePlans.get(plan).quote(stay);
