 22	    private static void assertPricing(String subtotal, String discount, String total, Pricing p) {
 23	        assertEquals(Money.of(subtotal), p.subtotal());
 24	        assertEquals(Money.of(discount), p.discount());
 25	        assertEquals(Money.of(total), p.total());
 26	    }
 27	
 28	    @Test
 29	    void highSeasonNightsAre20PercentHigher() {
 30	        assertPricing("599.76", "0", "599.76", quote("STANDARD", 101, "2027-07-10", "2027-07-12", null));
 31	    }
 32	
 33	    @Test
 34	    void seasonStartsOnDecember15() {
