119	/** Roda contra o PostgreSQL de DB_URL, mas num schema próprio que é apagado no fim. */
120	class ApiTest {
121	
122	    private static final ObjectMapper MAPPER = new ObjectMapper()
123	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
124	    private static final HttpClient HTTP = HttpClient.newHttpClient();
125	    private static String schema;
126	    private static Db db;
127	    private static Javalin app;
128	    private static String base;
129	
130	    @BeforeAll
131	    static void start() throws Exception {
132	        String url = System.getenv("DB_URL");
133	        assumeTrue(url != null, "DB_URL não definida");
134	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
135	        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
136	             Statement s = c.createStatement()) {
137	            s.execute("CREATE SCHEMA " + schema);
138	        }
139	        db = new Db(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema,
140	                System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
141	        ReservationRepository reservations = new ReservationRepository();
142	        app = new Api(new ReservationService(db, reservations, new MessageRepository()),
143	                new ReportService(db, reservations)).create().start(0);
144	        base = "http://localhost:" + app.port();
145	    }
146	
147	    @AfterAll
148	    static void stop() throws Exception {
149	        if (app != null) {
150	            app.stop();
151	            db.close();
152	            try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
153	                    System.getenv("DB_PASSWORD")); Statement s = c.createStatement()) {
154	                s.execute("DROP SCHEMA " + schema + " CASCADE");
155	            }
156	        }
157	    }
158	
159	    private static HttpResponse<String> send(String method, String path, String body) throws Exception {
160	        HttpRequest.Builder request = HttpRequest.newBuilder(URI.create(base + path));
161	        request.method(method, body == null ? HttpRequest.BodyPublishers.noBody()
162	                : HttpRequest.BodyPublishers.ofString(body));
163	        return HTTP.send(request.build(), HttpResponse.BodyHandlers.ofString());
164	    }
165	
166	    private static String booking(int room, String in, String out, int guests, String plan, String extra) {
167	        return "{\"roomNumber\":" + room + ",\"guestName\":\"Carla Dias\",\"guestEmail\":\"carla@example.com\","
168	                + "\"guestCpf\":\"111.222.333-44\",\"checkIn\":\"" + in + "\",\"checkOut\":\"" + out + "\","
169	                + "\"guests\":" + guests + ",\"ratePlan\":\"" + plan + "\"" + extra + "}";
170	    }
171	
172	    private static JsonNode create(String body) throws Exception {
173	        HttpResponse<String> response = send("POST", "/reservations", body);
174	        assertEquals(201, response.statusCode(), response.body());
175	        return MAPPER.readTree(response.body());
176	    }
177	
178	    private static void assertError(int status, String code, HttpResponse<String> response) throws Exception {
179	        assertEquals(status, response.statusCode(), response.body());
180	        assertEquals(code, MAPPER.readTree(response.body()).get("error").asText());
181	    }
