183	    @Test
184	    void listsRooms() throws Exception {
185	        JsonNode rooms = MAPPER.readTree(send("GET", "/rooms", null).body());
186	        assertEquals(5, rooms.size());
187	        assertEquals(249.90, rooms.get(0).get("nightlyRate").asDouble());
188	    }
