190	    @Test
191	    void fullLifecycleWithConfirmationEmailAndReceipt() throws Exception {
192	        JsonNode created = create(booking(201, "2030-03-11", "2030-03-13", 2, "CORPORATE",
193	                ",\"companyCode\":\"TECNOSUL\""));
194	        long id = created.get("id").asLong();
195	        String raw = send("GET", "/reservations/" + id, null).body();
196	        assertTrue(raw.contains("\"subtotal\":779.80") && raw.contains("\"amountPaid\":0.00")
197	                && raw.contains("\"refund\":null"), raw);
198	        assertEquals("PENDING", created.get("status").asText());
199	        assertEquals("779.80", created.get("subtotal").decimalValue().setScale(2).toPlainString());
200	        assertEquals("93.58", created.get("discount").decimalValue().setScale(2).toPlainString());
201	        assertEquals("686.22", created.get("total").decimalValue().setScale(2).toPlainString());
202	        assertEquals("0.00", created.get("amountPaid").decimalValue().setScale(2).toPlainString());
203	        assertTrue(created.get("refund").isNull());
204	
205	        assertError(409, "OPERATION_NOT_ALLOWED", send("GET", "/reservations/" + id + "/document", null));
206	        assertError(409, "OPERATION_NOT_ALLOWED", send("POST", "/reservations/" + id + "/check-in", null));
207	
208	        JsonNode confirmed = MAPPER.readTree(send("POST", "/reservations/" + id + "/confirmation", null).body());
209	        assertEquals("CONFIRMED", confirmed.get("status").asText());
210	        assertEquals("686.22", confirmed.get("amountPaid").decimalValue().setScale(2).toPlainString());
211	
212	        JsonNode messages = MAPPER.readTree(send("GET", "/messages", null).body());
213	        JsonNode message = messages.get(messages.size() - 1);
214	        assertEquals("EMAIL", message.get("channel").asText());
215	        assertEquals("carla@example.com", message.get("to").asText());
216	        assertEquals("Reserva confirmada - Pousada Maré Alta", message.get("subject").asText());
217	        assertEquals("Olá, Carla Dias!\n\nSua reserva na Pousada Maré Alta está confirmada. "
218	                + "Estes são os dados dela:\n\n"
219	                + "Comprovante de reserva nº " + id + "\n"
220	                + "Hóspede: Carla Dias (CPF 111.222.333-44)\n"
221	                + "Quarto: 201 (DELUXE)\n"
222	                + "Entrada: 11/03/2030 | Saída: 13/03/2030 | 2 diárias\n"
223	                + "Diárias: R$ 779,80\n"
224	                + "Desconto: R$ 93,58\n"
225	                + "Total: R$ 686,22\n\n"
226	                + "A entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!", message.get("body").asText());
227	
228	        assertError(409, "OPERATION_NOT_ALLOWED", send("POST", "/reservations/" + id + "/confirmation", null));
229	        assertEquals("CHECKED_IN",
230	                MAPPER.readTree(send("POST", "/reservations/" + id + "/check-in", null).body()).get("status").asText());
231	        assertError(409, "OPERATION_NOT_ALLOWED", send("POST", "/reservations/" + id + "/cancellation", null));
232	
233	        JsonNode receipt = MAPPER.readTree(send("POST", "/reservations/" + id + "/check-out", null).body());
234	        assertEquals("Comprovante de reserva", receipt.get("title").asText());
235	        assertEquals("DELUXE", receipt.get("roomType").asText());
236	        assertEquals("686.22", receipt.get("total").decimalValue().setScale(2).toPlainString());
237	        assertEquals(receipt, MAPPER.readTree(send("GET", "/reservations/" + id + "/document", null).body()));
238	    }
