240	    @Test
241	    void roomCannotBeBookedTwiceButCancelledFreesIt() throws Exception {
242	        String body = booking(101, "2030-05-10", "2030-05-12", 2, "STANDARD", "");
243	        long first = create(body).get("id").asLong();
244	        assertError(409, "ROOM_UNAVAILABLE", send("POST", "/reservations",
245	                booking(101, "2030-05-11", "2030-05-13", 1, "STANDARD", "")));
246	        create(booking(101, "2030-05-12", "2030-05-14", 1, "STANDARD", ""));
247	        send("POST", "/reservations/" + first + "/cancellation", null);
248	        create(body);
249	    }
