251	    @Test
252	    void cancellationRefundsFollowThePlan() throws Exception {
253	        long weekend = create(booking(201, "2030-03-15", "2030-03-17", 2, "WEEKEND_PACKAGE", "")).get("id").asLong();
254	        send("POST", "/reservations/" + weekend + "/confirmation", null);
255	        JsonNode cancelled = MAPPER.readTree(send("POST", "/reservations/" + weekend + "/cancellation", null).body());
256	        assertEquals("CANCELLED", cancelled.get("status").asText());
257	        assertEquals("410.00", cancelled.get("refund").decimalValue().setScale(2).toPlainString());
258	
259	        long nonRefundable = create(booking(202, "2030-03-15", "2030-03-17", 2, "NON_REFUNDABLE", "")).get("id")
260	                .asLong();
261	        send("POST", "/reservations/" + nonRefundable + "/confirmation", null);
262	        assertEquals("0.00", MAPPER.readTree(send("POST", "/reservations/" + nonRefundable + "/cancellation", null)
263	                .body()).get("refund").decimalValue().setScale(2).toPlainString());
264	
265	        long pending = create(booking(301, "2030-03-15", "2030-03-17", 2, "STANDARD", "")).get("id").asLong();
266	        assertEquals("0.00", MAPPER.readTree(send("POST", "/reservations/" + pending + "/cancellation", null)
267	                .body()).get("refund").decimalValue().setScale(2).toPlainString());
268	    }
