270	    @Test
271	    void rejectsInvalidRequests() throws Exception {
272	        assertError(400, "INVALID_REQUEST", send("POST", "/reservations", "não é json"));
273	        assertError(400, "INVALID_REQUEST", send("POST", "/reservations", "{}"));
274	        assertError(400, "INVALID_REQUEST",
275	                send("POST", "/reservations", booking(101, "2032-05-12", "2032-05-12", 1, "STANDARD", "")));
276	        assertError(400, "INVALID_REQUEST",
277	                send("POST", "/reservations", booking(101, "2032-05-10", "2032-05-12", 0, "STANDARD", "")));
278	        assertError(400, "INVALID_REQUEST",
279	                send("POST", "/reservations", booking(101, "2032-05-10", "2032-05-12", 1, "CORPORATE", "")));
280	        assertError(400, "INVALID_REQUEST",
281	                send("POST", "/reservations", booking(101, "2032-05-10", "2032-05-12", 1, "LONG_STAY", "")));
282	        assertError(400, "INVALID_REQUEST",
283	                send("POST", "/reservations", booking(101, "2032-05-10", "2032-05-12", 1, "WEEKEND_PACKAGE", "")));
284	        assertError(404, "ROOM_NOT_FOUND",
285	                send("POST", "/reservations", booking(999, "2032-05-10", "2032-05-12", 1, "STANDARD", "")));
286	        assertError(422, "CAPACITY_EXCEEDED",
287	                send("POST", "/reservations", booking(101, "2032-05-10", "2032-05-12", 3, "STANDARD", "")));
288	        assertError(404, "RESERVATION_NOT_FOUND", send("GET", "/reservations/99999", null));
289	        assertError(404, "RESERVATION_NOT_FOUND", send("POST", "/reservations/abc/confirmation", null));
290	        assertError(400, "INVALID_REQUEST", send("GET", "/reports/occupancy?date=10-07-2027", null));
291	        assertError(400, "INVALID_REQUEST", send("GET", "/reports/revenue?month=2027-13", null));
292	        assertError(400, "INVALID_REQUEST", send("GET", "/reports/revenue", null));
293	    }
