295	    @Test
296	    void reports() throws Exception {
297	        long paid = create(booking(102, "2031-07-10", "2031-07-12", 2, "STANDARD", "")).get("id").asLong();
298	        send("POST", "/reservations/" + paid + "/confirmation", null);
299	        long refunded = create(booking(101, "2031-07-11", "2031-07-13", 2, "NON_REFUNDABLE", "")).get("id").asLong();
300	        send("POST", "/reservations/" + refunded + "/confirmation", null);
301	        send("POST", "/reservations/" + refunded + "/cancellation", null);
302	        long pending = create(booking(201, "2031-07-11", "2031-07-13", 2, "STANDARD", "")).get("id").asLong();
303	
304	        HttpResponse<String> occupancy = send("GET", "/reports/occupancy?date=2031-07-11", null);
