306	        assertEquals("room,type,reservation,check_in,check_out\n102,STANDARD," + paid + ",2031-07-10,2031-07-12\n"
307	                + "total,1/5\n", occupancy.body());
308	        assertTrue(send("GET", "/reports/occupancy?date=2031-07-12", null).body().endsWith("total,0/5\n"));
309	
310	        String revenue = send("GET", "/reports/revenue?month=2031-07", null).body();
311	        assertEquals("reservation,room,check_in,check_out,status,amount\n"
312	                + paid + ",102,2031-07-10,2031-07-12,CONFIRMED,599.76\n"
313	                + refunded + ",101,2031-07-11,2031-07-13,CANCELLED,509.80\n"
314	                + "total,1109.56\n", revenue.replace(pending + ",", pending + ","));
315	    }
